mapper.select:
select co.*, c.name as className, s.name as subjectName,
       t.name as teacherName, sem.name as semesterName
from course co
left join class c on co.class_id = c.id
left join subject s on co.subject_id = s.id
left join teacher t on co.teacher_id = t.id
left join semester sem on co.semester_id = sem.id
where 1=1

    and co.class_id = #{dto.classId}


    and co.subject_id = #{dto.subjectId}


    and co.teacher_id = #{dto.teacherId}


    and co.semester_id = #{dto.semesterId}

order by co.id desc
